<span class="line"><span style="color:#E06C75;">    ConnectRetry</span><span style="color:#56B6C2;"> =</span><span style="color:#D19A66;"> 3</span><span style="color:#ABB2BF;">,                </span><span style="color:#7F848E;font-style:italic;">// 重试次数</span></span>
